import com.google.gson.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
public final class RuntimeArchiveAudit{
 static JsonArray failures=new JsonArray();static String s(JsonObject x,String k){return!x.has(k)||x.get(k).isJsonNull()?null:x.get(k).getAsString();}
 static void eq(String o,String m,String k,Object e,Object a){if(!Objects.equals(e,a)){JsonObject x=new JsonObject();x.addProperty("owner",o);x.addProperty("member",m);x.addProperty("key",k);x.add("expected",new Gson().toJsonTree(e));x.add("actual",new Gson().toJsonTree(a));failures.add(x);}}
 static List<String>strings(JsonElement x){List<String>r=new ArrayList<>();if(x!=null&&!x.isJsonNull())for(var e:x.getAsJsonArray())r.add(e.getAsString());return r;}
 static Object constant(JsonElement e,String d){if(e==null||e.isJsonNull())return null;return switch(d){case"Z","B","C","S","I"->e.getAsInt();case"J"->e.getAsLong();case"F"->e.getAsFloat();case"D"->e.getAsDouble();default->e.getAsString();};}
 public static void main(String[]a)throws Exception{
  var meta=JsonParser.parseString(Files.readString(Path.of(a[1]))).getAsJsonObject().getAsJsonObject("owners");var transport=JsonParser.parseString(Files.readString(Path.of(a[2]))).getAsJsonObject();Set<String>extras=new HashSet<>();for(var e:transport.getAsJsonArray("remaining_extras")){var x=e.getAsJsonObject();extras.add(s(x,"R_owner")+"."+s(x,"R_method"));}
  Map<String,ClassNode>classes=new HashMap<>();try(var z=new ZipFile(a[0])){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();if(!e.getName().endsWith(".class"))throw new IllegalArgumentException("Class-only R archive required");ClassNode c=new ClassNode();try(var in=z.getInputStream(e)){new ClassReader(in.readAllBytes()).accept(c,ClassReader.SKIP_CODE|ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}if(!e.getName().equals(c.name+".class")||classes.put(c.name,c)!=null)throw new IllegalArgumentException("Duplicate/incorrect class identity");}}
  int fields=0,methods=0,versions=0;for(var entry:meta.entrySet()){String o=entry.getKey();var x=entry.getValue().getAsJsonObject();var c=classes.get(o);if(c==null){eq(o,null,"present",true,false);continue;}eq(o,null,"access",x.get("access").getAsInt(),c.access&0xffff);eq(o,null,"super",s(x,"super"),c.superName);eq(o,null,"interfaces",strings(x.get("interfaces")),c.interfaces);eq(o,null,"signature",s(x,"signature"),c.signature);eq(o,null,"permits",strings(x.get("permitted_subclasses")),c.permittedSubclasses==null?List.of():c.permittedSubclasses);if(x.get("version").getAsInt()!=c.version)versions++;
   Map<String,FieldNode>fs=new HashMap<>();for(var f:c.fields)fs.put(f.name+f.desc,f);Set<String>expectedFields=new HashSet<>();for(var e:x.getAsJsonArray("fields")){var f=e.getAsJsonObject();String key=s(f,"name")+s(f,"descriptor");expectedFields.add(key);var g=fs.get(key);if(g==null){eq(o,key,"field_present",true,false);continue;}fields++;eq(o,key,"access",f.get("access").getAsInt(),g.access&0xffff);eq(o,key,"signature",s(f,"signature"),g.signature);eq(o,key,"constant",constant(f.get("constant_value"),s(f,"descriptor")),g.value);}eq(o,null,"field_set",expectedFields,fs.keySet());
   Map<String,MethodNode>ms=new HashMap<>();for(var m:c.methods)ms.put(m.name+m.desc,m);Set<String>expectedMethods=new HashSet<>();for(var e:x.getAsJsonArray("methods")){var m=e.getAsJsonObject();String key=s(m,"name")+s(m,"descriptor");expectedMethods.add(key);var n=ms.get(key);if(n==null){eq(o,key,"method_present",true,false);continue;}methods++;eq(o,key,"access",m.get("access").getAsInt(),n.access&0xffff);eq(o,key,"signature",s(m,"signature"),n.signature);eq(o,key,"exceptions",strings(m.get("exceptions")),n.exceptions);}for(String key:ms.keySet())if(!expectedMethods.contains(key)&&!extras.contains(o+"."+key))eq(o,key,"unlisted_extra",false,true);
  }var policy=JsonParser.parseString(Files.readString(Path.of(a[1]))).getAsJsonObject();eq(null,null,"owned_classes",policy.get("expected_owned_classes").getAsInt(),classes.size());eq(null,null,"original_R_classes",policy.get("expected_reference_R_classes").getAsInt(),meta.size());JsonObject r=new JsonObject();r.addProperty("status",failures.isEmpty()?"passed_Code_free_original_R_identity_audit":"failed_runtime_identity_audit");r.addProperty("classes",classes.size());r.addProperty("original_R_owners",meta.size());r.addProperty("generated_source_owners",classes.size()-meta.size());r.addProperty("original_R_fields",fields);r.addProperty("original_R_methods",methods);r.addProperty("JDK17_class_version_differences",versions);r.addProperty("failure_count",failures.size());r.add("failures",failures);r.addProperty("old_Code_frame_inputs",0);r.addProperty("application_classes_loaded",0);Files.writeString(Path.of(a[3]),new GsonBuilder().setPrettyPrinting().create().toJson(r),StandardOpenOption.CREATE_NEW);if(!failures.isEmpty())throw new IllegalStateException("Runtime declaration audit failed");System.out.println("runtime_identity_passed owners="+meta.size()+" fields="+fields+" methods="+methods);
 }
}
